    { type: 'essay', q: 'علل: يلتصق قميص السباحة بجسم السابح عند خروجه من الماء ولا يلتصق إذا كان مغموراً.', modelAnswer: 'إذا كان مغموراً فإن هناك قوة تلاصق بين الماء وقميص السباحة، وكذلك قوة تلاصق بين جسم السابح وقميص السباحة، وهاتان القوتان متساويتان. أما إذا خرج من الماء فستبقى فقط قوة التلاصق بين جسم السابح وقميص السباحة التي تجعل القميص يلتصق عند الخروج.' },
    { type: 'essay', q: 'علل: عند الضغط بالإصبع على السطح الداخلي لخيمة أثناء هطول المطر يناسب الماء من ذلك الموضع.', modelAnswer: 'لأن الضغط على القطرات يؤدي إلى تمزق الغشاء المرن الذي يحيط بالقطرة فيدخل الماء من مسامات الخيمة، أو أن حرارة جسم الإنسان تؤدي إلى نقصان الشد السطحي للقطرة فيتمزق الغشاء المرن فينتشر الماء خلال الخيمة.' },
    { type: 'essay', q: 'علل: تمتص المنشفة الرطبة الماء من الجلد أسرع من المنشفة الجافة.', modelAnswer: 'لأن شعيرات المنشفة الرطبة تكون أقل قطراً من الجافة بسبب الشد السطحي للماء الذي يجعلها أقل قطراً، فيكون سريان الماء فيها أسرع عند استعمالها في مص الماء من جلد الإنسان، أو أن المنشفة المبللة تزداد فيها قوة التلاصق للماء فتمتص الماء بسرعة.' }
