  questions: [
    { type: 'essay', q: 'ما سبب تألق الماس؟', modelAnswer: 'وذلك بسبب صغر زاويته الحرجة حيث حوالي 24.40 ومعامل انكساره كبير 2.42، فالضوء الساقط والنافذ الى داخله يعاني عدة انعكاسات كلية ثم يخرج فيكسب ذلك البريق واللمعان.' },
    { type: 'essay', q: 'أيهما أكثر عكسا للضوء: الموشور أم المرأة المستوية؟ ولاذا؟', modelAnswer: 'الموشور أكثر عكسا للضوء، لان الضوء في الموشور العاكس ينعكس انعكاسا كليا داخليا بنسبة 100%، اما في المرأة فيحصل امتصاص للضوء الساقط عليها فهي تعكس نسبة حوالي 90%.' },
    { type: 'essay', q: 'ما قانونا الانعكاس؟ وما قانونا الانكسار؟', modelAnswer: 'قانونا الانعكاس: 1- الشعاع الساقط والشعاع المنعكس والعمود المقام من نقطة السقوط تقع جميعها في مستو واحد. 2- زاوية السقوط = زاوية الانعكاس. قانونا الانكسار: 1- الشعاع الساقط والشعاع المنكسر والعمود المقام من نقطة السقوط على السطح الفاصل تقع جميعها في مستو واحد عمودي على السطح الفاصل بين وسطین شفافین. 2- النسبة بين جيب زاوية السقوط وجيب زاوية الانكسار يساوي مقدار ثابت.' },
    { type: 'essay', q: 'اذكر الصيغة الرياضية لقانوني سنيل موضحا المعنى الفيزيائي لكل رمز؟', modelAnswer: 'قانون سنيل: n₁ sinθ₁ = n₂ sinθ₂، حيث n₁ معامل الانكسار المطلق للوسط الشفاف الأول، sinθ₁ جيب زاوية السقوط فيه، n₂ معامل الانكسار المطلق للوسط الشفاف الثاني، sinθ₂ جيب زاوية الانكسار في الوسط الثاني.' },
    { type: 'essay', q: 'ماذا نقصد بالزاوية الحرجة؟ وما علاقتها بمعامل الانكسار المطلق لمادة شفافة؟', modelAnswer: 'الزاوية الحرجة هي زاوية السقوط في الوسط الاكثف ضوئيا والتي زاوية انكسارها قائمة 90° في الوسط الاقل نسبة كثافة ضوئية. والزاوية الحرجة لها علاقة بمعامل الانكسار المطلق لمادة شفافة هي: n = 1 / sinθc، حيث θc الزاوية الحرجة، n معامل الانكسار المطلق لمادة شفافة.' },
    { type: 'essay', q: 'ما المقصود بالقول إن معامل الانكسار المطلق للماء هو (1.33)؟', modelAnswer: 'معامل الانكسار المطلق لمادة ما هو النسبة بين سرعة الضوء في الفراغ وسرعة الضوء في الوسط الشفاف والذي هو الهواء او الماء، فيكون معامل الانكسار المطلق للماء = سرعة الضوء في الفراغ / سرعة الضوء في الوسط.' },
    { type: 'essay', q: 'في حالة ان يكون الشعاع (1) هو الشعاع الساقط. في الشكل المجاور فما هي الاشعة المنعكسة والاشعة المنكسرة من الاشعة الحمراء الاربعة الأخرى؟', modelAnswer: 'الشعاع 2,4 منعكسان والشعاع 3,5 منكسران.' }
  ]
